(6221109, 918031, 61396, '<td valign="top">Not that I understand the horse back, but the gloomy background make it for me.</td>', 'Not that I understand the horse back, but the gloomy background make it for me.', '2010-11-12 18:28:47.000000', NULL, 1),
(6221112, 919180, 61396, '<td valign="top">The great play of colors, reflections and shadows shape this up for me.</td>', 'The great play of colors, reflections and shadows shape this up for me.', '2010-11-12 18:36:12.000000', NULL, 1),
(6221116, 919054, 61396, '<td valign="top">Intriguing scene: it might be mundane (e.g. a birthday balloon after 9 days), but the high contrast allows my imagination to wonder, so thanks for that.</td>', 'Intriguing scene: it might be mundane (e.g. a birthday balloon after 9 days), but the high contrast allows my imagination to wonder, so thanks for that.', '2010-11-12 18:44:01.000000', NULL, 1),
(6221118, 917989, 61396, '<td valign="top">It shows the many ways a single scene can be presented and interpreted. I am dying to know what''s behind the wall to compare notes.</td>', 'It shows the many ways a single scene can be presented and interpreted. I am dying to know what''s behind the wall to compare notes.', '2010-11-12 18:45:59.000000', NULL, 1),
(6221120, 918170, 61396, '<td valign="top">I admit of not getting the connection with the title, but it doesn''t bother me too much, as I like the play of dark/bright laundry on top of the bright/dark wall. It says "shapes" to me.</td>', 'I admit of not getting the connection with the title, but it doesn''t bother me too much, as I like the play of dark/bright laundry on top of the bright/dark wall. It says "shapes" to me.', '2010-11-12 18:46:20.000000', NULL, 1),
(6221128, 918059, 108069, '<td valign="top">It''s certainly a cool scene, and it''s a great idea for the challenge, but something isn''t quite right. At the same time it seems oversharpened but not sharp enough. Great composition, though.</td>', 'It''s certainly a cool scene, and it''s a great idea for the challenge, but something isn''t quite right. At the same time it seems oversharpened but not sharp enough. Great composition, though.', '2010-11-12 19:03:50.000000', NULL, 1),
