(6221509, 918170, 30364, '<td valign="top">Hope lives in small spaces<br/>flies its whispered banners there<br/>Life is lived in quiet places<br/>a hearth, a heart, a bowl, a chair<br/> <br/>The empty crosses on the hilltops<br/>proclaim not faith but mortal fear<br/>The lines of laundry are our triumph<br/>proof of life and everywhere</td>', 'Hope lives in small spacesflies its whispered banners thereLife is lived in quiet placesa hearth, a heart, a bowl, a chair The empty crosses on the hilltopsproclaim not faith but mortal fearThe lines of laundry are our triumphproof of life and everywhere', '2010-11-13 10:14:34.000000', NULL, 1),
(6221572, 919182, 20799, '<td valign="top">Fantastic clarity and composition... one of my top picks.</td>', 'Fantastic clarity and composition... one of my top picks.', '2010-11-13 11:40:57.000000', NULL, 1),
