(6222036, 918999, 76335, '<td valign="top">I love your composition, and I don''t even mind that the table isn''t perfectly square (keystoning?). More distracting is that color balance/mixed lighting that shows up as different colors on different sides of the table.</td>', 'I love your composition, and I don''t even mind that the table isn''t perfectly square (keystoning?). More distracting is that color balance/mixed lighting that shows up as different colors on different sides of the table.', '2010-11-14 10:35:29.000000', NULL, 1),
(6222038, 919098, 76335, '<td valign="top">Good spiraling rhythm in this. I might have been tempted to go black and white, but the warm colors here hold up okay.</td>', 'Good spiraling rhythm in this. I might have been tempted to go black and white, but the warm colors here hold up okay.', '2010-11-14 10:36:59.000000', NULL, 1),
(6222041, 918952, 76335, '<td valign="top">A welcome enigma. Points for creativity.</td>', 'A welcome enigma. Points for creativity.', '2010-11-14 10:38:55.000000', NULL, 1),
