(6222052, 919099, 76335, '<td valign="top">A kindred spirit! I have something like this going on in the other challenge, and I''m paying the price for it. Anyway, I like what you''ve done here. Hope your score isn''t suffering too much.</td>', 'A kindred spirit! I have something like this going on in the other challenge, and I''m paying the price for it. Anyway, I like what you''ve done here. Hope your score isn''t suffering too much.', '2010-11-14 10:48:48.000000', NULL, 1),
(6222053, 919117, 76335, '<td valign="top">Very effective against the blinds and with the harp visible.</td>', 'Very effective against the blinds and with the harp visible.', '2010-11-14 10:51:14.000000', NULL, 1),
(6222054, 918505, 76335, '<td valign="top">Pure poetry. I love gnarly trees. Beautifully composed and processed.</td>', 'Pure poetry. I love gnarly trees. Beautifully composed and processed.', '2010-11-14 10:52:13.000000', NULL, 1),
(6222055, 918519, 76335, '<td valign="top">I love the feeling of adventure in this. Great point of view too.</td>', 'I love the feeling of adventure in this. Great point of view too.', '2010-11-14 10:52:53.000000', NULL, 1),
(6222069, 918903, 76335, '<td valign="top">Simple and quiet. I like the muted lighting.</td>', 'Simple and quiet. I like the muted lighting.', '2010-11-14 11:46:45.000000', NULL, 1),
(6222070, 919063, 76335, '<td valign="top">I like your idea, but the lighting is a bit flat and drab in this.</td>', 'I like your idea, but the lighting is a bit flat and drab in this.', '2010-11-14 11:47:10.000000', NULL, 1),
