(6222263, 918955, 114225, '<td valign="top">Great entry for this challenge. The colors are very nice, and the sharpness of the silhouette is great.</td>', 'Great entry for this challenge. The colors are very nice, and the sharpness of the silhouette is great.', '2010-11-14 16:06:11.000000', NULL, 1),
